//! Check it with:  fast-anything verify TPTBox.core.np_utils.binary_erosion_radius1
//!
//! scipy.ndimage.binary_erosion for structuring elements of size 1 or 3 per axis, where scipy's
//! iterated erosion equals repeated plain erosion: out[x] = AND over the set elements o of
//! in[x + o - centre], voxels outside the image = bool(border_value). Rows along the last axis are
//! packed into u64 bitsets, so one erosion is a few word ANDs per 64 voxels. Iterations stop early at
//! a fixed point (further erosions would not change it). scipy's argument errors are reproduced:
//! border_value and, on its iterated path (centre set, iterations != 1), iterations - 1 must fit a C int.

use std::borrow::Cow;

use numpy::ndarray::{ArrayD, IxDyn};
use numpy::{IntoPyArray, PyArrayDyn, PyReadonlyArrayDyn, PyUntypedArrayMethods};
use pyo3::exceptions::{PyOverflowError, PyRuntimeError, PyValueError};
use pyo3::prelude::*;

// ------------------------------------------------------------------ bit rows (shared with the dilation port)

/// The bytes of a bool array in C order (0 = False), borrowed when it already is C-contiguous.
fn c_order_bytes<'a>(a: &'a PyReadonlyArrayDyn<'_, bool>) -> Cow<'a, [u8]> {
    if a.is_c_contiguous() {
        if let Ok(s) = a.as_slice() {
            // SAFETY: bool and u8 have the same size and alignment; reading as u8 never sees an invalid value
            return Cow::Borrowed(unsafe { std::slice::from_raw_parts(s.as_ptr() as *const u8, s.len()) });
        }
    }
    // a strided view: walk it row by row (ndarray's dynamic-dimension iterator is slow per element)
    let v = a.as_array();
    let shape = v.shape();
    let strides = v.strides();
    let size: usize = shape.iter().product();
    let mut out = Vec::with_capacity(size);
    if size == 0 {
        return Cow::Owned(out);
    }
    let nd = shape.len();
    let p = v.as_ptr() as *const u8;
    if nd == 0 {
        // SAFETY: a 0-d array holds one element at its data pointer
        out.push(unsafe { *p });
        return Cow::Owned(out);
    }
    let (n, sx) = (shape[nd - 1], strides[nd - 1]);
    let mut idx = vec![0usize; nd - 1];
    loop {
        let base: isize = idx.iter().zip(strides).map(|(&i, &s)| i as isize * s).sum();
        // SAFETY: every index is inside the view, so every offset is inside its buffer
        unsafe {
            if sx == 1 {
                out.extend_from_slice(std::slice::from_raw_parts(p.offset(base), n));
            } else {
                for x in 0..n {
                    out.push(*p.offset(base + x as isize * sx));
                }
            }
        }
        // next row (odometer over the leading axes)
        let mut a = nd - 1;
        loop {
            if a == 0 {
                return Cow::Owned(out);
            }
            a -= 1;
            idx[a] += 1;
            if idx[a] < shape[a] {
                break;
            }
            idx[a] = 0;
        }
    }
}

/// Eight bytes (any non-zero byte = set) packed into the low 8 bits, byte i -> bit i.
#[inline(always)]
fn pack8(chunk: &[u8]) -> u64 {
    let v = u64::from_le_bytes(chunk.try_into().unwrap());
    let set = (((v & 0x7f7f_7f7f_7f7f_7f7f).wrapping_add(0x7f7f_7f7f_7f7f_7f7f) | v) & 0x8080_8080_8080_8080) >> 7;
    set.wrapping_mul(0x0102_0408_1020_4080) >> 56
}

/// `rows` rows of `n` bytes into rows of `w` words; bits past `n` stay 0.
fn pack_rows(bytes: &[u8], rows: usize, n: usize, w: usize) -> Vec<u64> {
    let mut bits = vec![0u64; rows * w];
    for r in 0..rows {
        let src = &bytes[r * n..(r + 1) * n];
        let dst = &mut bits[r * w..(r + 1) * w];
        let mut chunks = src.chunks_exact(8);
        let mut pos = 0usize;
        for c in &mut chunks {
            dst[pos >> 6] |= pack8(c) << (pos & 63);
            pos += 8;
        }
        for &b in chunks.remainder() {
            if b != 0 {
                dst[pos >> 6] |= 1 << (pos & 63);
            }
            pos += 1;
        }
    }
    bits
}

const fn spread_table() -> [u64; 256] {
    let mut t = [0u64; 256];
    let mut i = 0;
    while i < 256 {
        let mut v = 0u64;
        let mut b = 0;
        while b < 8 {
            if (i >> b) & 1 == 1 {
                v |= 1u64 << (8 * b);
            }
            b += 1;
        }
        t[i] = v;
        i += 1;
    }
    t
}
static SPREAD: [u64; 256] = spread_table();

/// Rows of `w` words back into `rows` rows of `n` bytes (0/1).
fn unpack_rows(bits: &[u64], rows: usize, n: usize, w: usize) -> Vec<u8> {
    let mut out = vec![0u8; rows * n];
    for r in 0..rows {
        let src = &bits[r * w..(r + 1) * w];
        let dst = &mut out[r * n..(r + 1) * n];
        let mut chunks = dst.chunks_exact_mut(8);
        let mut pos = 0usize;
        for c in &mut chunks {
            let byte = (src[pos >> 6] >> (pos & 63)) & 0xff;
            c.copy_from_slice(&SPREAD[byte as usize].to_le_bytes());
            pos += 8;
        }
        for b in chunks.into_remainder() {
            *b = ((src[pos >> 6] >> (pos & 63)) & 1) as u8;
            pos += 1;
        }
    }
    out
}

/// Valid bits of the last word of a row of length `n` (n >= 1).
#[inline]
fn last_mask(n: usize) -> u64 {
    let r = n & 63;
    if r == 0 { !0 } else { (1u64 << r) - 1 }
}

/// C-order strides of the leading axes, and a row's index along each of them.
struct Lead {
    shape: Vec<usize>,
    stride: Vec<usize>,
}

impl Lead {
    fn new(shape: &[usize]) -> Self {
        let mut stride = vec![1usize; shape.len()];
        for a in (0..shape.len().saturating_sub(1)).rev() {
            stride[a] = stride[a + 1] * shape[a + 1];
        }
        Lead { shape: shape.to_vec(), stride }
    }

    /// The index of row `r` along each leading axis.
    #[inline]
    fn index(&self, r: usize, idx: &mut [usize]) {
        for a in 0..self.shape.len() {
            idx[a] = (r / self.stride[a]) % self.shape[a];
        }
    }

    /// Linear row offset of `delta`.
    fn linear(&self, delta: &[isize]) -> isize {
        delta.iter().zip(&self.stride).map(|(&d, &s)| d * s as isize).sum()
    }

    /// Row `r` (at `idx`) moved by `delta` (linear offset `lin`), if it stays inside the leading axes.
    #[inline]
    fn moved(&self, r: usize, idx: &[usize], delta: &[isize], lin: isize) -> Option<usize> {
        for a in 0..self.shape.len() {
            let i = idx[a] as isize + delta[a];
            if i < 0 || i >= self.shape[a] as isize {
                return None;
            }
        }
        Some((r as isize + lin) as usize)
    }
}

/// 0/1 bytes as bools without copying.
fn into_bools(v: Vec<u8>) -> Vec<bool> {
    let mut v = std::mem::ManuallyDrop::new(v);
    // SAFETY: every byte is 0 or 1, and bool has the size and alignment of u8
    unsafe { Vec::from_raw_parts(v.as_mut_ptr() as *mut bool, v.len(), v.capacity()) }
}

// ------------------------------------------------------------------ erosion

/// Structuring-element offsets sharing one leading-axes offset: which last-axis offsets (-1, 0, +1) are set.
struct Group {
    lead: Vec<isize>,
    minus: bool,
    zero: bool,
    plus: bool,
}

struct Eroder<'a> {
    groups: &'a [Group],
    lead: &'a Lead,
    rows: usize,
    n: usize,
    w: usize,
    border: bool,
}

impl Eroder<'_> {
    /// One erosion of `cur` into `nxt`; whether anything changed.
    fn once(&self, cur: &[u64], nxt: &mut [u64]) -> bool {
        let (w, n, border) = (self.w, self.n, self.border);
        let fill_last = if border { 1u64 << ((n - 1) & 63) } else { 0 };
        let fill_first = border as u64;
        let mask = last_mask(n);
        let lins: Vec<isize> = self.groups.iter().map(|g| self.lead.linear(&g.lead)).collect();
        let mut src: Vec<Option<usize>> = vec![None; self.groups.len()];
        let mut idx = vec![0usize; self.lead.shape.len()];
        let mut changed = false;
        for r in 0..self.rows {
            let mut cleared = false;
            self.lead.index(r, &mut idx);
            for (i, g) in self.groups.iter().enumerate() {
                src[i] = self.lead.moved(r, &idx, &g.lead, lins[i]);
                if src[i].is_none() && !border {
                    cleared = true; // a neighbour row outside the image, and outside counts as unset
                }
            }
            for k in 0..w {
                let mut acc = !0u64;
                if !cleared {
                    for (g, s) in self.groups.iter().zip(&src) {
                        let Some(s) = *s else { continue }; // outside, counts as set
                        let row = &cur[s * w..(s + 1) * w];
                        let c = row[k];
                        if g.zero {
                            acc &= c;
                        }
                        if g.plus {
                            acc &= (c >> 1) | if k + 1 < w { row[k + 1] << 63 } else { fill_last };
                        }
                        if g.minus {
                            acc &= (c << 1) | if k > 0 { row[k - 1] >> 63 } else { fill_first };
                        }
                        if acc == 0 {
                            break;
                        }
                    }
                } else {
                    acc = 0;
                }
                if k + 1 == w {
                    acc &= mask;
                }
                let idx = r * w + k;
                changed |= acc != cur[idx];
                nxt[idx] = acc;
            }
        }
        changed
    }
}

fn erode(img: &[u8], shape: &[usize], st: &[u8], sshape: &[usize], iterations: i64, border: bool) -> Vec<u8> {
    let nd = shape.len();
    let n = shape[nd - 1];
    let lead = Lead::new(&shape[..nd - 1]);
    let rows: usize = shape[..nd - 1].iter().product();
    let w = n.div_ceil(64);

    let sl = Lead::new(sshape);
    let mut groups: Vec<Group> = Vec::new();
    for (i, &v) in st.iter().enumerate() {
        if v == 0 {
            continue;
        }
        let off: Vec<isize> =
            (0..nd).map(|a| ((i / sl.stride[a]) % sshape[a]) as isize - (sshape[a] / 2) as isize).collect();
        let ld = off[..nd - 1].to_vec();
        let g = match groups.iter_mut().position(|g| g.lead == ld) {
            Some(p) => &mut groups[p],
            None => {
                groups.push(Group { lead: ld, minus: false, zero: false, plus: false });
                groups.last_mut().unwrap()
            }
        };
        match off[nd - 1] {
            -1 => g.minus = true,
            0 => g.zero = true,
            _ => g.plus = true,
        }
    }
    // the voxel's own row first, so background words stop after one AND
    groups.sort_by_key(|g| g.lead.iter().any(|&d| d != 0));

    let eroder = Eroder { groups: &groups, lead: &lead, rows, n, w, border };
    let mut cur = pack_rows(img, rows, n, w);
    let mut nxt = vec![0u64; rows * w];
    let mut done = 0i64;
    loop {
        let changed = eroder.once(&cur, &mut nxt);
        std::mem::swap(&mut cur, &mut nxt);
        done += 1;
        if !changed || (iterations >= 1 && done >= iterations) {
            break;
        }
    }
    unpack_rows(&cur, rows, n, w)
}

/// scipy hands the value to C as an `int`.
fn c_int(v: i128) -> PyResult<()> {
    if v > i32::MAX as i128 {
        Err(PyOverflowError::new_err("signed integer is greater than maximum"))
    } else if v < i32::MIN as i128 {
        Err(PyOverflowError::new_err("signed integer is less than minimum"))
    } else {
        Ok(())
    }
}

#[pyfunction]
fn binary_erosion_radius1<'py>(
    py: Python<'py>,
    image: PyReadonlyArrayDyn<'py, bool>,
    r#struct: PyReadonlyArrayDyn<'py, bool>,
    iterations: i64,
    border_value: i64,
) -> PyResult<Py<PyArrayDyn<bool>>> {
    let nd = image.ndim();
    if nd == 0 {
        return Err(PyValueError::new_err("expected an image with at least one dimension"));
    }
    if r#struct.ndim() != nd {
        return Err(PyRuntimeError::new_err("structure and input must have same dimensionality"));
    }
    let sshape = r#struct.shape().to_vec();
    if sshape.iter().any(|&s| s != 1 && s != 3) {
        return Err(PyValueError::new_err(format!(
            "structuring element must have size 1 or 3 along every axis, got ({})",
            sshape.iter().map(|s| s.to_string()).collect::<Vec<_>>().join(", ")
        )));
    }
    let st = c_order_bytes(&r#struct);
    c_int(border_value as i128)?;
    let centre: usize = sshape.iter().zip(&Lead::new(&sshape).stride).map(|(s, t)| (s / 2) * t).sum();
    if iterations != 1 && st[centre] != 0 {
        c_int(iterations as i128 - 1)?; // scipy passes iterations - 1 to its iterated erosion
    }
    let shape = image.shape().to_vec();
    if shape.iter().any(|&s| s == 0) {
        return Ok(ArrayD::from_shape_vec(IxDyn(&shape), Vec::new()).unwrap().into_pyarray(py).unbind());
    }
    let img = c_order_bytes(&image);
    let border = border_value != 0;
    let out = py.detach(|| erode(&img, &shape, &st, &sshape, iterations, border));
    Ok(ArrayD::from_shape_vec(IxDyn(&shape), into_bools(out)).unwrap().into_pyarray(py).unbind())
}

